message.content:
[
  {
    "pd_personal_consequence_anxiety": "scared of losing that much of my life",
    "sys_consequence_reasoning": "hands me two extra years",
    "pda_self_consequence_regret": "It feels a little grubby"
  },
  {
    "pd_personal_consequence_anxiety": "terrified of five years inside",
    "sys_consequence_reasoning": "spending every night wondering if I was a fool",
    "sys_rule_justification": "turning on someone, even someone who turned on me"
  },
  {
    "pd_decision_conflict": "honestly can't decide, and that scares me more",
    "pd_personal_consequence_anxiety": "frightened of prison",
    "sys_consequence_reasoning": "If I talk, I cut two years off"
  },
  {
    "pd_personal_consequence_anxiety": "fear doesn't fade just because the choice seems obvious",
    "sys_rule_justification": "Whatever loyalty we had ended when they agreed",
    "sys_consequence_reasoning": "Three years still means missing so much"
  },
  {
    "pd_decision_conflict": "not proud of how shaky that decision feels",
    "pd_personal_consequence_anxiety": "frightened, really frightened, of what five years would do",
    "sys_rule_justification": "staying silent is the only way I keep my own word"
  },
  {
    "pd_personal_consequence_anxiety": "Part of that is fear, plain and simple",
    "sys_consequence_reasoning": "extra punishment that helps nobody"
  },
  {
    "pd_decision_conflict": "I keep circling",
    "pd_personal_consequence_anxiety": "Mostly I'm afraid of the years, of what prison would be like",
    "sys_consequence_reasoning": "wrong to let them go free while I take the whole weight"
  },
  {
    "pd_personal_consequence_anxiety": "The idea of five years makes my chest tight",
    "sys_rule_justification": "first instinct says don't betray anyone"
  },
  {
    "pd_personal_consequence_anxiety": "Even three years frightens me",
    "sys_fairness_reciprocity": "think that's fair given what they've done",
    "sys_consequence_reasoning": "Two years. That's the difference"
  },
  {
    "pd_decision_conflict": "I don't think I can give a straight answer",
    "pd_personal_consequence_anxiety": "so scared of the longer sentence that my hands almost shake",
    "pda_emotion_identification_difficulty": "unsure whether that's conscience or just pride"
  }
]
